<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\TemplateAsset\Domain\ValueObject\Accessor\TemplateAssetContentAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TemplateAssetContentAccessor trait.
 *
 * Covers null default, string/VO assignment via withContent,
 * getContent/content accessors, and isContentChanged with/without original.
 */
class TemplateAssetContentAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withContent creates a new instance with the Content set
     * from a string value, and getContent returns the primitive string.
     */
    public function testWithContentFromString(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetContentAccessorUnitTest();

        // Act
        $result = $holder->withContent('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->getContent());
    }
    /**
     * Asserts that withcontent has access to the value object
     * from a string value, and getContent returns the primitive string.
     */
    public function testWithContentFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetContentAccessorUnitTest();

        // Act
        $result = $holder->withContent('store://bin');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('bin', $result->content()->value());
    }
    public function testChangedContent(): void
    {
        // Arrange
        $holder = new ImplWithTemplateAssetContentAccessorUnitTest()->withContent('store://bin');
        $original = $holder->withContent('store://bin');
        $same = $holder->withContent('store://bin');
        $modified = $holder->withContent('store://obin');

        // Act
        $withSame = $original->isContentChanged($same);
        $withDiferent = $original->isContentChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTemplateAssetContentAccessorUnitTest
{
    use TemplateAssetContentAccessor;
}
